export const SAMPLE_DOCUMENT = `# Release process update: weekday deploys

## Why we are changing

For the past two years our team has frozen all production deployments on Fridays, a rule introduced after a painful weekend incident in 2022 that was entirely reasonable at the time but has since hardened into a habit nobody questions, even though it slows down every sprint, pushes risky changes into the early part of the week when the team is already stretched thin by planning and support duties, and makes it harder to ship the small fixes that customers are actually waiting for.

Our pipeline has changed a lot since then. Every deploy now runs automated smoke tests, rolls out to ten percent of traffic first, and reverts itself if the error rate rises. The Friday freeze no longer protects us from much.

Honestly, the old freeze was a total pain and everyone kinda hated it. So we're ditching it, no big deal, but please don't be that person who pushes a huge change at 5pm on Friday and then vanishes for the weekend lol.

## What changes

Starting on the first of next month, you may deploy on any weekday, as long as the following conditions are met:

- Tests are passing on the main branch
- Get a review from a second engineer
- Rollback plan, you must write one in the pull request.
- No deploys during the on-call handover

All deploys need a reviewed pull request. Nothing may be deployed without a review. Every deployment has to be approved by a reviewer first.

To start a canary rollout, run the deploy script from the repository root:

\`\`\`bash
./scripts/deploy --env production --canary 10
./scripts/deploy --status
\`\`\`

Once the canary looks healthy, you will recieve a prompt to promote it to all traffic. If anything looks wrong, the rollback happens automatically and the on-call engineer is notified.

If you have questions about the new process, ask in the #releases channel or contact Priya on the platform team.
`
import type { ProxyOptions } from 'vite'
import { describe, expect, it } from 'vitest'
import {
  buildOpenRouterProxy,
  buildOpenRouterProxyTable,
  OPENROUTER_PROXY_PREFIX,
  OPENROUTER_TARGET,
  rewriteOpenRouterPath,
  setAuthorization,
} from './openrouter-proxy'

type ProxyServerArg = Parameters<NonNullable<ProxyOptions['configure']>>[0]
type ProxyReqHandler = (proxyReq: FakeProxyReq) => void

type FakeProxyReq = {
  readonly setHeader: (name: string, value: string) => void
  readonly headers: () => Record<string, string>
}

const createFakeProxyReq = (initial: Record<string, string>): FakeProxyReq => {
  const headers = new Map(
    Object.entries(initial).map(([name, value]) => [name.toLowerCase(), value]),
  )
  return {
    setHeader: (name, value) => {
      headers.set(name.toLowerCase(), value)
    },
    headers: () => Object.fromEntries(headers),
  }
}

const captureProxyReqHandler = (options: ProxyOptions): ProxyReqHandler => {
  const handlers: ProxyReqHandler[] = []
  const fakeProxy = {
    on: (event: string, handler: ProxyReqHandler) => {
      if (event === 'proxyReq') handlers.push(handler)
    },
  }
  options.configure?.(fakeProxy as unknown as ProxyServerArg, options)
  const [handler] = handlers
  if (!handler) throw new Error('proxyReq handler was not registered')
  return handler
}

describe('rewriteOpenRouterPath', () => {
  it('strips the proxy prefix', () => {
    expect(rewriteOpenRouterPath('/api/openrouter/models')).toBe('/models')
  })

  it('keeps nested paths and query strings', () => {
    expect(rewriteOpenRouterPath('/api/openrouter/generation?id=gen-1')).toBe(
      '/generation?id=gen-1',
    )
  })
})

describe('setAuthorization', () => {
  it('overwrites whatever Authorization the browser sent', () => {
    const proxyReq = createFakeProxyReq({ Authorization: 'Bearer placeholder' })
    setAuthorization('real-key')(proxyReq)
    expect(proxyReq.headers().authorization).toBe('Bearer real-key')
  })

  it('adds Authorization when the browser sent none', () => {
    const proxyReq = createFakeProxyReq({})
    setAuthorization('real-key')(proxyReq)
    expect(proxyReq.headers().authorization).toBe('Bearer real-key')
  })
})

describe('buildOpenRouterProxy', () => {
  it('targets OpenRouter with changeOrigin and the prefix rewrite', () => {
    const options = buildOpenRouterProxy('real-key')
    expect(options.target).toBe(OPENROUTER_TARGET)
    expect(options.changeOrigin).toBe(true)
    expect(options.rewrite?.('/api/openrouter/models')).toBe('/models')
  })

  it('overwrites Authorization on every proxied request', () => {
    const handler = captureProxyReqHandler(buildOpenRouterProxy('real-key'))

    const first = createFakeProxyReq({ authorization: 'Bearer placeholder' })
    handler(first)
    const second = createFakeProxyReq({})
    handler(second)

    expect(first.headers().authorization).toBe('Bearer real-key')
    expect(second.headers().authorization).toBe('Bearer real-key')
  })
})

describe('buildOpenRouterProxyTable', () => {
  it('registers a single entry under the prefix', () => {
    const table = buildOpenRouterProxyTable('real-key')
    expect(Object.keys(table)).toEqual([OPENROUTER_PROXY_PREFIX])
  })
})
import type { ProxyOptions } from 'vite'

export const OPENROUTER_PROXY_PREFIX = '/api/openrouter/'
export const OPENROUTER_TARGET = 'https://openrouter.ai/api/v1'

type HeaderSetter = {
  readonly setHeader: (name: string, value: string) => void
}

export const rewriteOpenRouterPath = (path: string): string =>
  path.replace(/^\/api\/openrouter/, '')

export const setAuthorization =
  (apiKey: string) =>
  (proxyReq: HeaderSetter): void => {
    proxyReq.setHeader('Authorization', `Bearer ${apiKey}`)
  }

export const buildOpenRouterProxy = (apiKey: string): ProxyOptions => ({
  target: OPENROUTER_TARGET,
  changeOrigin: true,
  rewrite: rewriteOpenRouterPath,
  configure: (proxy) => {
    proxy.on('proxyReq', setAuthorization(apiKey))
  },
})

export const buildOpenRouterProxyTable = (
  apiKey: string,
): Record<string, ProxyOptions> => ({
  [OPENROUTER_PROXY_PREFIX]: buildOpenRouterProxy(apiKey),
})
