  it('strips ATX markers', () => {
    expect(headingText(byText('## Section A'))).toBe('Section A')
  })

  it('strips closing ATX markers', () => {
    const [block] = extractBlocks('## Closed ##\n')
    expect(block && headingText(block)).toBe('Closed')
  })

