      from: block.from + 2,
      to: block.from + 5,
    })
    expect(target).toMatchObject({
      source: 'selection',
      from: block.from + 2,
      to: block.from + 5,
      text: 'two',
    })
    expect(target?.blocks.map((candidate) => candidate.id)).toEqual([block.id])
  })

