  id: 'gen-abc',
  model: 'vendor/model-a',
  provider_name: 'Acme',
  latency: 1620,
  generation_time: 1410,
  finish_reason: 'stop',
  tokens_prompt: 800,
  tokens_completion: 110,
  native_tokens_reasoning: 25,
  native_tokens_cached: 5,
  total_cost: 0.0005,
}

const base = {
  task: 'select paragraph 2 → Shorter',
