import { createOpenRouter } from '@openrouter/ai-sdk-provider'
import { generateText, Output, registerTelemetry, streamText } from 'ai'
import { it } from 'vitest'
import { reviewEditSchema, suggestionSchema } from './schemas'

const sse = (chunks: readonly unknown[], delayMs = 0) => {
  const encoder = new TextEncoder()
  return new Response(
    new ReadableStream({
      async start(controller) {
        for (const chunk of chunks) {
          controller.enqueue(encoder.encode(`data: ${JSON.stringify(chunk)}\n\n`))
          if (delayMs) await new Promise((r) => setTimeout(r, delayMs))
        }
        controller.enqueue(encoder.encode('data: [DONE]\n\n'))
        controller.close()
      },
    }),
    { headers: { 'content-type': 'text/event-stream' } },
  )
}

const events: string[] = []
registerTelemetry({
  onStart: (e) => { events.push(`start ${e.callId} ${e.modelId} ctx=${JSON.stringify((e as { runtimeContext?: unknown }).runtimeContext)}`) },
  onLanguageModelCallEnd: (e) => { events.push(`lmEnd ${e.callId} ${e.modelId} ${e.responseId} ${e.finishReason} ${JSON.stringify(e.usage)} ${JSON.stringify(e.providerMetadata)} ${JSON.stringify(e.performance)}`) },
  onEnd: (e) => { events.push(`end ${e.callId}`) },
  onError: (e) => { events.push(`error ${JSON.stringify((e as {callId?: string}).callId)} ${String((e as {error?: unknown}).error)}`) },
  onAbort: (e) => { events.push(`abort ${e.callId}`) },
  onStepError: (e) => { events.push(`stepError ${e.callId}`) },
})

const mk = (fetchStub: typeof fetch) =>
  createOpenRouter({ baseURL: 'http://localhost/api/openrouter', apiKey: 'p', fetch: fetchStub, compatibility: 'strict' }).chat('vendor/m', { provider: { require_parameters: true }, reasoning: { effort: 'low' } })

it('stream 402', async () => {
  const model = mk(async () => new Response(JSON.stringify({ error: { code: 402, message: 'Insufficient credits' } }), { status: 402, headers: { 'content-type': 'application/json' } }))
  let captured: unknown
  const s = streamText({ model, prompt: 'x', output: Output.array({ element: reviewEditSchema }), maxRetries: 1, onError: ({ error }) => { captured = error } })
  const got: unknown[] = []
  try { for await (const e of s.elementStream) got.push(e) ; console.log('loop ended, no throw') } catch (e) { console.log('loop threw', String(e)) }
  try { await s.output } catch (e) { console.log('output threw', (e as Error).name, String(e).slice(0, 200)) }
  console.log('captured', (captured as Error)?.name, String(captured).slice(0, 200))
  console.log(events.splice(0).join('\n'))
})

it('generate 402', async () => {
  const model = mk(async () => new Response(JSON.stringify({ error: { code: 402, message: 'Insufficient credits' } }), { status: 402, headers: { 'content-type': 'application/json' } }))
  try { await generateText({ model, prompt: 'x', output: Output.object({ schema: suggestionSchema }), maxRetries: 1 }) } catch (e) { console.log('gen threw', (e as Error).name, String(e).slice(0, 200)) }
  console.log(events.splice(0).join('\n'))
})

it('stream ok two elements', async () => {
  const content = '{"elements":[{"blockId":"p1","replacement":"A","rationale":"r"},{"blockId":"p2","replacement":"B","rationale":"r"}]}'
  const parts = content.match(/.{1,20}/g) ?? []
  const chunks = [
    ...parts.map((p, i) => ({ id: 'gen-9', model: 'vendor/m-served', provider: 'Acme', choices: [{ delta: { role: 'assistant', content: p }, finish_reason: null }] })),
    { id: 'gen-9', choices: [{ delta: {}, finish_reason: 'stop' }], usage: { prompt_tokens: 100, completion_tokens: 40, total_tokens: 140, cost: 0.0002, completion_tokens_details: { reasoning_tokens: 3 } } },
  ]
  const model = mk(async () => sse(chunks, 20))
  const t0 = performance.now()
  const s = streamText({ model, prompt: 'x', output: Output.array({ element: reviewEditSchema }), maxRetries: 0, runtimeContext: { requestId: 'r1' }, telemetry: { functionId: 'review', includeRuntimeContext: { requestId: true } }, onError: () => {} })
  for await (const e of s.elementStream) console.log('el', Math.round(performance.now() - t0), JSON.stringify(e))
  console.log('output', Math.round(performance.now() - t0), JSON.stringify(await s.output))
  await new Promise((r) => setTimeout(r, 50))
  console.log(events.splice(0).join('\n'))
})

it('timeout', async () => {
  const model = mk(async (_i, init) => new Promise((_res, rej) => { init?.signal?.addEventListener('abort', () => rej(init.signal?.reason)) }))
  try { await generateText({ model, prompt: 'x', output: Output.object({ schema: suggestionSchema }), maxRetries: 1, timeout: 200 }) } catch (e) { console.log('timeout threw', (e as Error).name, String(e).slice(0, 200), 'cause', ((e as Error).cause as Error)?.name) }
  console.log(events.splice(0).join('\n'))
})
