    readonly requestId: string
    readonly task: string
    readonly attempt: number
    readonly outcome: CallOutcome
    readonly startedAt: string
    readonly timing: CallTiming
    readonly failure: ClientError | undefined
  }): void => {
    track(
      (async () => {
        const observation = await collector.expect(input.requestId, model)
        const generation = await fetchGeneration({
          baseURL,
          apiKey,
          id: observation.responseId,
          fetch: config.fetch,
          delaysMs: config.generationDelaysMs,
        })
        config.onRecord?.(
          shapeAiCallRecord({
            task: input.task,
            attempt: input.attempt,
            outcome: input.outcome,
            startedAt: input.startedAt,
            timing: input.timing,
            observation: {
              ...observation,
              requestedModel: model,
              error: input.failure?.type,
            },
            generation,
          }),
        )
      })(),
