  }

  const callSettings = (
    requestId: string,
    task: string,
    kind: keyof RequestKindLimits,
    abortSignal: AbortSignal,
  ) => ({
    model: buildModel(),
    maxRetries,
    maxOutputTokens: maxOutputTokens[kind],
    timeout: { totalMs: timeoutsMs[kind] },
    abortSignal,
    runtimeContext: { requestId },
    telemetry: {
      functionId: task,
      includeRuntimeContext: { requestId: true },
    },
  })

  const runTargetAttempt = async (
    parts: PromptParts,
    original: string,
    task: string,
    attempt: number,
    signal: AbortSignal | undefined,
  ): Promise<Result<SuggestionResult>> => {
    const requestId = generateId()
    collector.expect(requestId, model).catch(() => undefined)
    const startedAt = new Date().toISOString()
    const startedMs = clock()
    const settle = (failure: ClientError | undefined): void =>
      emitRecord({
        requestId,
        task,
        attempt,
        outcome: outcomeOf(failure),
        startedAt,
        timing: { clientTotalMs: Math.round(clock() - startedMs) },
        failure,
      })
    try {
      const result = await generateText({
        ...callSettings(requestId, task, 'target', signal ?? new AbortController().signal),
        instructions: parts.instructions,
        prompt: parts.prompt,
        output: Output.object({ schema: suggestionSchema }),
      })
      const check = checkSuggestion(original, result.output)
      if (check.type === 'invalid') {
        const failure: ClientError = {
          type: 'invalid-output',
          message: `Replacement was ${check.reason}`,
        }
        settle(failure)
        return { ok: false, error: failure }
      }
      settle(undefined)
      return { ok: true, value: check.suggestion }
    } catch (error) {
      const failure = classifyError(error)
      settle(failure)
      return { ok: false, error: failure }
    }
  }

  return {
    model,
    requestSuggestion: async () => {
      throw new Error('not implemented')
    },
    refineSuggestion: async () => {
      throw new Error('not implemented')
    },
