    const status = describeOutcome(result)
    if (result.outcome.type !== 'suggestion')
      return `${heading}\n\n${status}`
    const { replacement, rationale, unchanged } = result.outcome.payload
    return [
      `${heading} (${status}${unchanged ? ', unchanged' : ''})`,
      '',
