        })
        continue
      }
      const result = await (spec.kind === 'quick'
        ? runQuick(client, spec)
        : runReview(client, spec)
      ).catch(
        (error: unknown): RequestResult => ({
          requestId: spec.id,
          task: taskLabel(spec),
          wallMs: 0,
          outcome: {
            type: 'error',
            error: {
              type: 'unknown',
              message: error instanceof Error ? error.message : String(error),
            },
          },
        }),
      )
